{"command":"cat > UITap/NavigationTests.swift <<'EOF'
import XCTest

final class NavigationTests: XCTestCase {
    func testNavigate() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.terminate()
        app.launch()
        sleep(2)
        app.buttons["User menu"].tap()
        sleep(1)
        app.coordinate(withNormalizedOffset: CGVector(dx: 0.34, dy: 0.14)).tap()
        sleep(2)
        print("LABELS=" + app.staticTexts.allElementsBoundByIndex.map { $0.label }.joined(separator: " | "))
        print("BUTTONS=" + app.buttons.allElementsBoundByIndex.map { $0.label }.joined(separator: " | "))
        print("TREE=\n\(app.debugDescription)")
    }
}
EOF
